```cpp
const byte PIN_TOMBOL = 4;
int klik = 0;
unsigned long lastDebounce = 0;
int lastReading = HIGH;

void IRAM_ATTR tombolISR() {
  klik++;
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_TOMBOL, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(PIN_TOMBOL), tombolISR, FALLING);
}

void loop() {
  int baca = digitalRead(PIN_TOMBOL);
  delay(20);
  if (baca != lastReading) {
    lastReading = baca;
    lastDebounce = millis();
  }
  if (millis() > lastDebounce + 50) {
    static int terakhirKirim = -1;
    if (klik != terakhirKirim) {
      terakhirKirim = klik;
      Serial.println(klik);
    }
  }
}
```

