#include <DHT.h>

#define DHTPIN 5
DHT dht(DHTPIN, DHT11);

unsigned long lastRead = 0;

void setup() {
  Serial.begin(115200);
  dht.begin();
}

void loop() {
  if (millis() - lastRead >= 100) {
    lastRead = millis();
    float h = dht.readHumidity();
    int t = dht.readTemperature();
    if (isnan(h)) {
      Serial.println("gagal baca");
      return;
    }
    Serial.print("T=");
    Serial.println(t);
  }
}
